def create_metadata_rows_for_datasets(apps, schema_editor):
    Dataset = apps.get_model("vitrina_datasets", "Dataset")
    ContentType = apps.get_model("contenttypes", "ContentType")
    Metadata = apps.get_model("vitrina_structure", "Metadata")
    Version = apps.get_model("vitrina_structure", "Version")
    dataset_content_type = ContentType.objects.get_for_model(Dataset)

    for dataset in Dataset.objects.all():
        draft_metadata_version = Version.objects.filter(dataset=dataset, status=VersionStatus.DRAFT).order_by("-version").first()
        if not Metadata.objects.filter(dataset=dataset, content_type=dataset_content_type).exists():
            dataset_name = generate_unique_dataset_name(dataset.organization, dataset)
            Metadata.objects.create(
                uuid=str(uuid.uuid4()),
                dataset=dataset,
                content_type=dataset_content_type,
                object_id=dataset.pk,
                name=dataset_name,
                title=dataset.title,
                description=dataset.description,
                prepare_ast={},
                version=1,
                metadata_version=draft_metadata_version,
            )


def delete_orphaned_distributions(apps, schema_editor):
    DatasetDistribution = apps.get_model("vitrina_resources", "DatasetDistribution")
    ContentType = apps.get_model("contenttypes", "ContentType")
    Metadata = apps.get_model("vitrina_structure", "Metadata")
    dd_ct = ContentType.objects.get_for_model(DatasetDistribution)
    for metadata in Metadata.objects.filter(content_type_id=dd_ct).all():
        distribution = DatasetDistribution.objects.filter(pk=metadata.object_id).first()
        if not distribution:
            metadata.delete()


def fix_dataset_distributions(apps, schema_editor):
    Dataset = apps.get_model("vitrina_datasets", "Dataset")
    DatasetDistribution = apps.get_model("vitrina_resources", "DatasetDistribution")
    ContentType = apps.get_model("contenttypes", "ContentType")
    Metadata = apps.get_model("vitrina_structure", "Metadata")
    Version = apps.get_model("vitrina_structure", "Version")
    dd_ct = ContentType.objects.get_for_model(DatasetDistribution)

    for dataset in Dataset.objects.all():
        draft_version_of_the_dataset = Version.objects.filter(dataset=dataset, status=VersionStatus.DRAFT).order_by("-version").first()
        for distribution in dataset.datasetdistribution_set.all():

            distribution_metadata = Metadata.objects.filter(
                content_type=dd_ct,
                object_id=distribution.pk
            )

            if distribution.model_set.exists():
                if distribution.format and distribution.format.extension == "UAPI":
                    distribution_metadata.all().delete()
                    distribution.metadata_version = None
                    distribution.save(update_fields=['metadata_version'])

                    for model in distribution.model_set.all():
                        model.distribution = None
                        model.save(update_fields=['distribution'])
                    continue

                distribution.metadata_version = draft_version_of_the_dataset
                existing_metadata = distribution_metadata.first()
                if existing_metadata:
                    existing_metadata.metadata_version = draft_version_of_the_dataset
                    existing_metadata.save(update_fields=['metadata_version'])

                else:
                    name = distribution.name
                    if not name:
                        latest_name = (
                            Metadata.objects.filter(
                                dataset=dataset,
                                content_type=dd_ct,
                                name__iregex=r"resource[0-9]+",
                            )
                            .order_by("name")
                            .values_list("name", flat=True)
                            .last()
                        )
                        if not latest_name:
                            latest_name = "resource1"
                        else:
                            duplicate_name_suffix = latest_name.replace("resource", "")
                            try:
                                duplicate_name_suffix = int(duplicate_name_suffix)
                            except ValueError:
                                duplicate_name_suffix = 0
                            duplicate_name_suffix += 1
                            latest_name = f"resource{duplicate_name_suffix}"
                        name = latest_name

                    Metadata.objects.create(
                        uuid=str(uuid.uuid4()),
                        dataset=distribution.dataset,
                        content_type=dd_ct,
                        object_id=distribution.pk,
                        name=name,
                        prepare_ast={},
                        access=distribution.access or None,
                        version=1,
                        title=distribution.title,
                        description=distribution.description,
                        level_given=distribution.level,
                        metadata_version=draft_version_of_the_dataset,
                    )
                distribution.save(update_fields=['metadata_version'])

            else:
                distribution_metadata.all().delete()
                distribution.metadata_version = None
                distribution.save(update_fields=['metadata_version'])


